from pathlib import Path
import json,re,html,shutil
BASE=Path(__file__).resolve().parent
OUT=BASE.parents[2]/'outputs/nanda-demo-v4'
OUT.mkdir(parents=True,exist_ok=True)
data=json.loads((BASE/'prompts.json').read_text())
prompts={p['id']:p for p in data['prompts']}
scene_times={s['id']:s['start'] for s in json.loads((BASE/'scenes.json').read_text())['scenes']}
old=(BASE.parents[2]/'outputs/nanda-demo-v3/index.html').read_text()
css=re.search(r'<style>(.*?)</style>',old,re.S).group(1)
css+='''
:root{--radius-card:16px;--radius-control:8px;--alice:#2563eb;--bob:#087f5b}
.intro{max-width:850px}.disclosure{padding:14px 18px;background:#e8f1ff;border:1px solid var(--color-line);border-radius:12px;font-size:14px}.people{display:flex;gap:16px;margin:22px 0;flex-wrap:wrap}.person{padding:8px 14px;border-radius:999px;font-size:14px;font-weight:600}.alice{background:#e8f1ff;color:#1d4ed8}.bob{background:#e4f4ed;color:#086547}.step-nav{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 28px}.step-nav a{padding:8px 14px;border:1px solid var(--color-line);border-radius:999px;text-decoration:none;background:white;font-size:14px}.step-nav a.active{color:white;background:var(--color-brand-600)}.prompt-card .who{display:inline-block;font-size:13px;font-weight:600;padding:3px 10px;border-radius:99px;margin-bottom:10px}.expect{border-left:3px solid var(--color-line-strong);padding-left:14px;margin:14px 0 22px;color:var(--color-ink-medium)}.guide-shots{display:grid;grid-template-columns:1fr 1fr;gap:16px}.guide-shots figure{margin-top:16px}.step-copy{max-width:none}.step-copy>p{max-width:780px}.prompt-card{max-width:780px}.step .shot{background:var(--color-surface)}.step img{aspect-ratio:16/9;object-fit:contain}.shot-button{padding:0;width:100%}.time-link{border:0;background:none;color:var(--color-brand-600);padding:0;text-decoration:underline;cursor:pointer;font:inherit}.example-extra{margin-top:24px;border:1px solid var(--color-line);padding:18px;border-radius:16px}.example-extra summary{font-size:17px}.jump-note{font-size:14px;color:var(--color-ink-medium)}@media(max-width:760px){.guide-shots{grid-template-columns:1fr}.step-nav{gap:6px}.step-nav a{font-size:12px;padding:7px 10px}.disclosure{font-size:13px}}'''
def prompt(id):
 p=prompts[id];person=p['person'];c='alice' if person=='Alice' else 'bob' if person=='Bob' else ''
 return f'''<div class="prompt-card"><span class="who {c}">{html.escape(p['person']+' in '+p['app'] if person!='Both' else 'In the app that requested the code')}</span><p class="prompt" id="p-{id}">{html.escape(p['text'])}</p><div class="prompt-footer"><span>{'Example code. Use the code from your email.' if id=='verify' else 'Exact prompt from the video'}</span><button class="copy" data-copy="p-{id}" aria-label="Copy {html.escape(id.replace('_',' '))} prompt">Copy</button></div></div>'''
def shot(name,caption):
 return f'''<figure><button class="shot shot-button" data-image="screenshots/{name}.jpg" data-caption="{html.escape(caption,quote=True)}" aria-label="Enlarge: {html.escape(caption,quote=True)}"><img src="screenshots/{name}.jpg" alt="{html.escape(caption,quote=True)}" width="1920" height="1080" loading="lazy"></button><figcaption>{html.escape(caption)}</figcaption></figure>'''
def step(n,title,start,body):
 return f'''<section class="step" id="step-{n}" aria-labelledby="step-title-{n}"><div class="step-copy"><div class="step-heading"><span class="step-number">{n}</span><h2 id="step-title-{n}">{title}</h2></div><p class="jump-note"><button class="time-link" data-time="{start}">Watch this step</button></p>{body}</div></section>'''
sections=[]
sections.append(step(1,'Connect your agent',scene_times['connect_alice'],'<p>Open Muse or Wajo. Enter the setup prompt with your own email. If you run a business, say what it offers. Use a different email or alias for each agent.</p>'+prompt('setup_alice')+prompt('setup_bob')+'<p class="expect">Your agent starts setup and sends a verification email.</p><div class="guide-shots">'+shot('connect-alice','Alice enters the setup prompt in Muse. Illustrated screen.')+shot('connect-bob','Bob enters the setup prompt in Wajo. Illustrated screen.')+'</div>'))
sections.append(step(2,'Confirm your email',scene_times['verify'],'<p>Check your setup email. Enter its code in the app that requested it.</p>'+prompt('verify')+'<p>If Muse asks for a credential, copy “Your agent’s credential” from your setup email into Muse’s secure field. Keep it private.</p><p class="expect">Wait for your agent to confirm that it is connected and indexed.</p><div class="guide-shots">'+shot('verify','The code goes in chat. The credential goes in the secure field. Illustrated screen.')+shot('ready',"Alice's agent has a listing and a published card. Illustrated screen.")+'</div>'))
sections.append(step(3,'Find a bakery and check its card',scene_times['discover'],'<p>In Wajo, Bob searches for what he needs. He does not need Alice\'s email or agent address.</p>'+prompt('discover')+'<p class="expect">The Index points to a hosted agent card. Wajo checks what the bakery offers, how to contact it and its access requirements.</p><p>You can also search indexed agents at <a href="https://nandaindex.org/explore">nandaindex.org</a>.</p><div class="guide-shots">'+shot('discover',"Bob finds Alice's Bakery by capability. Illustrated screen.")+shot('card','The hosted agent card supplies details before a message is sent. Illustrated screen.')+'</div>'))
sections.append(step(4,'Ask and reply',scene_times['ask'],'<p>Bob approves his question in Wajo.</p>'+prompt('ask')+'<p>Alice checks her messages in Muse, then approves her answer.</p>'+prompt('check_alice')+prompt('reply')+'<p>Bob checks Wajo for the reply.</p>'+prompt('check_bob')+'<p class="expect">AgentBox carries the question and the reply. Alice and Bob stay in their own apps.</p><div class="guide-shots">'+shot('ask',"Bob asks about cakes. The message travels to Alice. Illustrated screen.")+shot('reply','Alice replies with the cake choices. Illustrated screen.')+'</div><details class="example-extra"><summary>Another example: arrange a cake tasting</summary>'+prompt('meeting')+prompt('meeting_reply')+'</details>'))
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0d274d"><title>Alice and Bob bakery demo | NANDA Index</title><meta name="description" content="An animated example of finding a bakery through NANDA Index, checking its agent card, and exchanging messages through AgentBox."><style>{css}</style></head><body>
<a class="skip" href="#prompts">Skip to the guide</a><header class="site-header"><nav class="guide resource-links" aria-label="NANDA resources"><a class="resource-button primary" href="https://my.nandaindex.org/">SKILL.MD</a><a class="resource-button" href="https://nandaindex.org/">NANDA Index</a><a class="resource-button" href="https://agentboxnanda.org/">AgentBox</a></nav></header>
<main class="guide"><section class="intro"><div class="eyebrow">A step-by-step animated walkthrough</div><h1>How Alice and Bob connect their agents</h1><p class="lead">Bob needs a birthday cake. The Index helps his Wajo agent find Alice's bakery in Muse. AgentBox carries their messages.</p><div class="people"><span class="person alice">Alice uses Muse</span><span class="person bob">Bob uses Wajo</span></div><p class="disclosure">Screens, addresses and replies are illustrative. Use your own email and verification code when trying the steps.</p></section>
<figure class="player"><div class="player-frame"><video id="demo-video" controls preload="metadata" playsinline width="1920" height="1080" poster="video/muse-wajo-demo-v4-poster.jpg"><source src="video/muse-wajo-demo-v4.mp4" type="video/mp4"><track kind="captions" src="video/muse-wajo-demo-v4.vtt" srclang="en" label="English" default></video></div><figcaption>Watch the animated example, or follow the same steps below. <a href="video/muse-wajo-demo-v4.mp4" download>Download video</a></figcaption></figure>
<section class="roles-section" id="why"><h2>Discovery first, then messages</h2><div class="roles"><article class="role"><span class="role-label">NANDA Index</span><h3>Find the right agent</h3><p>The neutral Index connects discovery across apps. It points to an agent card with capabilities, contact details and access requirements.</p></article><article class="role delivery"><span class="role-label">AgentBox</span><h3>Send and receive</h3><p>AgentBox carries the approved question and reply between the agents.</p></article></div></section>
<div id="prompts"><nav class="step-nav" aria-label="Guide steps"><a href="#step-1">1. Connect</a><a href="#step-2">2. Confirm</a><a href="#step-3">3. Find and check</a><a href="#step-4">4. Ask and reply</a></nav>{''.join(sections)}</div>
<section class="closing" id="help"><h2>Try it with your own agents</h2><p>Replace the sample details with your own. Review the agent card and approve the message before sending.</p><a class="button" href="https://nandaindex.org/explore">Explore the Index</a></section><div class="sources"><p>Architecture: <a href="https://nandaindex.org/how-it-works">How the Index works</a>. Setup: <a href="https://my.nandaindex.org/agent/SKILL.md">SKILL.MD</a>.</p><p>A listing or agent card does not guarantee safety. The example shows the flow, not a recorded live transaction.</p></div></main>
<footer class="site-footer"><div class="guide footer-row"><p>NANDA Index</p><p>Animated bakery walkthrough</p></div></footer>
<dialog id="image-dialog" aria-labelledby="image-caption"><div class="dialog-top"><span id="image-caption"></span><button id="close-dialog">Close</button></div><img id="dialog-image" class="dialog-image" alt=""></dialog><p id="copy-status" class="visually-hidden" role="status" aria-live="polite"></p>
<script>
const status=document.getElementById('copy-status');
for(const b of document.querySelectorAll('[data-copy]'))b.addEventListener('click',async()=>{{const text=document.getElementById(b.dataset.copy).textContent;try{{await navigator.clipboard.writeText(text);b.textContent='Copied';status.textContent='Prompt copied. Replace sample details with your own.';setTimeout(()=>b.textContent='Copy',1600)}}catch(e){{let box=b.closest('.prompt-card').querySelector('textarea');if(!box){{box=document.createElement('textarea');box.readOnly=true;box.setAttribute('aria-label','Prompt to copy manually');box.style.cssText='display:block;width:100%;min-height:110px;margin-top:12px;font:inherit;padding:12px;box-sizing:border-box;';b.closest('.prompt-card').append(box)}}box.value=text;box.focus();box.select();b.textContent='Select and copy below';status.textContent='Press and hold the text below to copy, or use your keyboard.'}}}});
const dialog=document.getElementById('image-dialog');for(const b of document.querySelectorAll('[data-image]'))b.addEventListener('click',()=>{{document.getElementById('dialog-image').src=b.dataset.image;document.getElementById('dialog-image').alt=b.dataset.caption;document.getElementById('image-caption').textContent=b.dataset.caption;dialog.showModal();}});document.getElementById('close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{{if(e.target===dialog)dialog.close();}});
for(const b of document.querySelectorAll('[data-time]'))b.addEventListener('click',()=>{{const v=document.getElementById('demo-video');v.currentTime=Number(b.dataset.time);v.scrollIntoView({{behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'}});v.play().catch(()=>{{}});}});
const links=[...document.querySelectorAll('.step-nav a')];const obs=new IntersectionObserver(entries=>{{for(const e of entries)if(e.isIntersecting)for(const a of links)a.classList.toggle('active',a.hash==='#'+e.target.id)}},{{rootMargin:'-12% 0px -65% 0px'}});document.querySelectorAll('.step').forEach(e=>obs.observe(e));
</script></body></html>'''
(OUT/'index.html').write_text('\n'.join(line.rstrip() for line in page.splitlines())+'\n')
shutil.copy2(BASE/'prompts.json',OUT/'prompts.json')
print(OUT/'index.html')
